/* Original mobile layout; navigation patterns inspired by Ionic and Konsta UI. */
const mobilePreviousNav=hubNav;
hubNav=function(){let html=mobilePreviousNav();html=html.replace('</header>','<button class="mobile-menu-toggle" data-mobile-menu aria-expanded="false" aria-label="打开工具菜单"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 6h16M4 12h16M4 18h16"/></svg></button></header>');return html+`<nav class="mobile-tabs" aria-label="手机主导航"><button data-hub="home" ${view==='hub'?'aria-current="page"':''}><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m3 10 9-7 9 7v10h-6v-7H9v7H3z"/></svg>学习</button><button data-hub="books" ${view==='books'||view==='reader'?'aria-current="page"':''}><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 3h14a2 2 0 0 1 2 2v15H6a2 2 0 0 1-2-2zM4 16h16M8 7h8M8 11h6"/></svg>书房</button><button data-account="open" ${view==='account'?'aria-current="page"':''}><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/></svg>我的</button><button data-mobile-menu aria-expanded="false"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 6h16M4 12h16M4 18h16"/></svg>工具</button></nav>`;};
document.addEventListener('click',e=>{const toggle=e.target.closest('[data-mobile-menu]');if(toggle){const header=document.querySelector('.hub-header');const open=header.classList.toggle('mobile-menu-open');document.querySelectorAll('[data-mobile-menu]').forEach(b=>b.setAttribute('aria-expanded',String(open)));return;}if(!e.target.closest('.hub-header nav')||e.target.closest('.hub-header nav button')){document.querySelector('.hub-header')?.classList.remove('mobile-menu-open');document.querySelectorAll('[data-mobile-menu]').forEach(b=>b.setAttribute('aria-expanded','false'));}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('.hub-header')?.classList.remove('mobile-menu-open');document.querySelectorAll('[data-mobile-menu]').forEach(b=>b.setAttribute('aria-expanded','false'));}});
const mobilePreviousRender=render;render=function(){mobilePreviousRender();document.body.dataset.mobileView=view;document.querySelectorAll('body > .mobile-tabs').forEach(n=>n.remove());const tabs=document.querySelector('#app .mobile-tabs');if(tabs)document.body.append(tabs);const bar=document.querySelector('#app > .subject-bar');if(bar&&!document.querySelector('.classroom-switcher')){const wrapper=document.createElement('details');wrapper.className='classroom-switcher mobile-subject-picker';const summary=document.createElement('summary');summary.textContent='切换课堂';bar.replaceWith(wrapper);wrapper.append(summary,bar);}if(['account','books','reader','jp-library','guide','glossary','anime','incident','demos','manual','labs','roadmap'].includes(view))document.querySelector('.classroom-switcher')?.setAttribute('hidden','');paginateMobileBooks();};
let bookShelfPage=0;
function paginateMobileBooks(){if(view!=='books')return;const cards=[...document.querySelectorAll('.book-grid .book-card')],size=innerWidth<=700?6:9,total=Math.ceil(cards.length/size);if(total<=1)return;bookShelfPage=Math.max(0,Math.min(bookShelfPage,total-1));cards.forEach((c,i)=>c.hidden=i<bookShelfPage*size||i>=(bookShelfPage+1)*size);const nav=document.createElement('div');nav.className='route-pager';nav.setAttribute('aria-label','书架翻页');nav.innerHTML=`<button data-book-page="-1" ${bookShelfPage===0?'disabled':''}>上一页书籍</button><span>${bookShelfPage+1} / ${total} 页</span><button data-book-page="1" ${bookShelfPage===total-1?'disabled':''}>下一页书籍</button>`;document.querySelector('.book-grid').after(nav);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-book-page]');if(b&&!b.disabled){bookShelfPage+=Number(b.dataset.bookPage);render();document.querySelector('.book-grid')?.scrollIntoView({block:'start'});}if(e.target.closest('[data-hub="book-filter"]')){bookShelfPage=0;render();}});
render();
